"use client";
import {useCallback,useEffect,useState} from "react"; import ConsoleLayout from "@/components/layout/ConsoleLayout"; import {api} from "@/lib/api"; import type {CacheEntry} from "@/lib/types";
function TTL({entry}:{entry:CacheEntry}){const [now,setNow]=useState(0);useEffect(()=>{const update=()=>setNow(Date.now());const first=window.setTimeout(update,0);const x=window.setInterval(update,1000);return()=>{clearTimeout(first);clearInterval(x)}},[]);if(!now)return <>—</>;return <>{Math.max(0,Math.floor((new Date(entry.expires_at).getTime()-now)/1000))} sec</>}
export default function Cache(){const [items,setItems]=useState<CacheEntry[]>([]),[error,setError]=useState("");const load=useCallback(()=>api.cache().then(setItems).catch(e=>setError(e.message)),[]);useEffect(()=>{void load()},[load]);async function clear(){if(confirm("Clear every cached DNS response?")){await api.clearCache();void load()}}return <ConsoleLayout><section className="p-5 max-w-[1500px] mx-auto"><p className="label">TTL-aware local records</p><h1 className="text-2xl font-semibold mt-1">DNS Cache Explorer</h1><div className="mt-4 flex gap-2"><button onClick={()=>void load()} className="border border-line px-3 py-2 rounded">Refresh</button><button onClick={()=>void clear()} className="border border-red-700 text-red-300 px-3 py-2 rounded">Clear cache</button></div>{error?<p className="text-miss mt-4">{error}</p>:!items.length?<p className="panel p-6 mt-5 muted">Your DNS cache is empty.</p>:<div className="panel mt-5 overflow-x-auto"><table className="w-full text-sm"><thead className="text-left label"><tr>{["Domain","Type","IP / Response","TTL","Hits","Last Accessed","Action"].map(x=><th className="p-3" key={x}>{x}</th>)}</tr></thead><tbody>{items.map(e=><tr key={`${e.domain}-${e.record_type}`} className="border-t border-line"><td className="p-3">{e.domain}</td><td>{e.record_type}</td><td>{e.ip_addresses.join(", ")}</td><td className="text-cyan"><TTL entry={e}/></td><td>{e.hits}</td><td>{new Date(e.last_accessed).toLocaleTimeString()}</td><td><button onClick={async()=>{await api.removeCache(e.domain);void load()}} className="text-red-300">Delete</button></td></tr>)}</tbody></table></div>}</section></ConsoleLayout>}
